script:
html { scroll-behavior: smooth; }
::selection { background: var(--b8d21f6e-4c93-4a07-8e15-2f7a9c3db007, #2470E8); color: #FFFFFF; }
body { -webkit-font-smoothing: antialiased; }

/* reveal on scroll, armed only when motion is allowed */
html.pr-motion .pr-rise { opacity: 0; transform: translateY(16px); }
html.pr-motion .pr-rise.pr-in {
  opacity: 1; transform: none;
  transition: opacity 0.8s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.8s cubic-bezier(0.22, 1, 0.36, 1);
}
html.pr-motion .pr-d1.pr-in { transition-delay: 0.1s; }
html.pr-motion .pr-d2.pr-in { transition-delay: 0.2s; }
html.pr-motion .pr-d3.pr-in { transition-delay: 0.3s; }

/* logo marquee: duplicate set exists only for the loop, hide it when static */
.pr-marquee { animation: pr-scroll 30s linear infinite; }
@keyframes pr-scroll { to { transform: translateX(-50%); } }
@media (prefers-reduced-motion: reduce) {
  .pr-marquee { animation: none; justify-content: center; width: 100%; }
  .pr-marquee .pr-dup { display: none; }
}

/* buttons + cards */
.pr-btn { transition: transform 0.18s ease, opacity 0.18s ease; }
.pr-btn:hover { opacity: 0.92; transform: translateY(-1px); }
.pr-btn:active { transform: translateY(0) scale(0.99); }
.pr-card {
  transition: transform 0.25s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.25s ease;
}
.pr-card:hover {
  box-shadow: 0 14px 30px -18px rgba(17, 24, 38, 0.25);
  transform: translateY(-3px);
}
.pr-link { transition: color 0.18s ease; }
.pr-link:hover { color: var(--b8d21f6e-4c93-4a07-8e15-2f7a9c3db007, #2470E8); }

/* tabs: pill switcher with JS, labelled stacked panels without */
.pr-tab { cursor: pointer; transition: background-color 0.2s, color 0.2s, box-shadow 0.2s; }
.pr-tab[aria-selected="true"] {
  background-color: var(--b8d21f6e-4c93-4a07-8e15-2f7a9c3db001, #FFFFFF); box-shadow: 0 1px 3px rgba(17, 24, 38, 0.1); color: var(--b8d21f6e-4c93-4a07-8e15-2f7a9c3db002, #111826);
}
html:not(.pr-js) .pr-tabs { display: none; }
html.pr-js .pr-tablabel { display: none; }
html.pr-js .pr-tabpanel { display: none; }
html.pr-js .pr-tabpanel.pr-active { display: flex; }

/* accordion */
.pr-acc summary { cursor: pointer; list-style: none; }
.pr-acc summary::-webkit-details-marker { display: none; }
.pr-acc .pr-acc-icon { transition: transform 0.25s ease; }
.pr-acc[open] .pr-acc-icon { transform: rotate(45deg); }

a:focus-visible, button:focus-visible, summary:focus-visible {
  border-radius: 6px; outline: 2px solid var(--b8d21f6e-4c93-4a07-8e15-2f7a9c3db007, #2470E8); outline-offset: 3px;
}
